#!/bin/bash
# Manual GitHub Release Creation Guide

echo "============================================"
echo "Manual Release Creation for v1.0.0"
echo "============================================"
echo ""

echo "The automated workflow may not have run. Here's how to create the release manually:"
echo ""

echo "Step 1: Build the Distribution Packages"
echo "----------------------------------------"
echo "Run this command:"
echo "  cd dist && ./build-release.sh"
echo ""
read -p "Press Enter when you've built the packages (or skip if already done)..."
echo ""

echo "Step 2: Go to GitHub Releases"
echo "----------------------------------------"
echo "Open this URL in your browser:"
echo "  https://github.com/visit-www/Frcr-examiner/releases/new"
echo ""
read -p "Press Enter when you're on the page..."
echo ""

echo "Step 3: Fill in Release Details"
echo "----------------------------------------"
echo "Tag: v1.0.0 (select existing tag from dropdown)"
echo "Release title: FRCR Examiner Tool v1.0.0"
echo ""
echo "For the description, copy the content from:"
echo "  dist/RELEASE_NOTES.md"
echo ""
read -p "Press Enter when you've filled the details..."
echo ""

echo "Step 4: Upload Files"
echo "----------------------------------------"
echo "Upload these files from: release-v1.0.0/"
echo "  - FRCR-Examiner-Windows-v1.0.0.zip"
echo "  - FRCR-Examiner-macOS-v1.0.0.zip"
echo "  - checksums.txt"
echo ""
read -p "Press Enter when files are uploaded..."
echo ""

echo "Step 5: Publish Release"
echo "----------------------------------------"
echo "Click 'Publish release' button"
echo ""

echo "============================================"
echo "Alternative: Delete Old Tag and Retry"
echo "============================================"
echo ""
echo "If you want to remove the old v2.0-desktop tag:"
echo "  git tag -d v2.0-desktop"
echo "  git push origin :refs/tags/v2.0-desktop"
echo ""
echo "Then the v1.0.0 release will be the 'latest'"
echo ""
